        current_pos += l

    if block_idx == 0:
        return config, True

    block_i = config[block_idx]
    new_config = [block_i] + config[:block_idx] + config[block_idx+1:]

    i = 0
    while i < len(new_config) - 1:
        if new_config[i][0] == new_config[i+1][0]:
            new_config[i] = [new_config[i][0], new_config[i][1] + new_config[i+1][1]]
            new_config.pop(i+1)
        else:
            i += 1
    return new_config, False

def check(n, k):
    configs = []
    # To optimize, only generate configurations that have at least one block of each type
    # (unless n=0, which isn't the case).
    # Actually, let's just generate all and filter.
    for p in itertools.product([0, 1], repeat=2*n):
        if sum(p) == n:
            config = []
            curr_type = p[0]
            curr_len = 1
            for i in range(1, 2*n):
                if p[i] == curr_type:
                    curr_len += 1
                else:
                    config.append([curr_type, curr_len])
                    curr_type = p[i]
                    curr_len = 1
            config.append([curr_type, curr_len])
            configs.append(config)

    for config in configs:
        curr_config = config
        visited = []
        while True:
            if len(curr_config) <= 2:
                break
            if curr_config in visited:
                return False
            visited.append(curr_config)

            next_config, stable = get_next_state_final(curr_config, k)
            if stable:
                if len(next_config) > 2:
                    return False
                break
            curr_config = next_config
    return True

