def solve_for_n(n, k):
    def get_next_state(state, k):
        idx = k - 1
        coin = state[idx]
        left = idx
        while left > 0 and state[left-1] == coin:
            left -= 1
        right = idx
        while right < len(state)-1 and state[right+1] == coin:
            right += 1
        sub = state[left:right+1]
        new_state = sub + state[:left] + state[right+1:]
        return new_state

    def is_final(state):
        count = 0
        for i in range(len(state)-1):
            if state[i] != state[i+1]:
                count += 1
        return count <= 1

    def simulate(state, k):
        visited = set()
        curr = list(state)
        while True:
            s_tuple = tuple(curr)
            if s_tuple in visited:
                return False
            visited.add(s_tuple)
            if is_final(curr):
                return True
            curr = get_next_state(curr, k)

