def solve():
    def is_good(row):
        boundaries = 0
        for i in range(len(row) - 1):
            if row[i] != row[i+1]:
                boundaries += 1
        return boundaries <= 1

    def get_next(row, k):
        idx = k - 1
        metal = row[idx]
        start = idx
        while start > 0 and row[start-1] == metal:
            start -= 1
        end = idx
        while end < len(row) - 1 and row[end+1] == metal:
            end += 1
        sub = row[start:end+1]
        remaining = row[:start] + row[end+1:]
        return sub + remaining

    def check_k(na, nc, k):
        import itertools
        configs = list(itertools.combinations(range(na + nc), na))
        all_configs = []
        for config in configs:
            row = ['C'] * (na + nc)
            for i in config:
                row[i] = 'A'
            all_configs.append(tuple(row))

        for start_config in all_configs:
            current = list(start_config)
            visited = set()
            while True:
                if is_good(current):
                    break
                t_current = tuple(current)
                if t_current in visited:
                    return False
                visited.add(t_current)
                current = list(get_next(current, k))
